import type { Handler } from './http.ts';
import type { ApiResult } from './api.ts';

// A teammate stubbed the types with any and skipped validation.
export type CreateBooking = any;
export type Booking = any;

export const createBooking: Handler<{}, {}, CreateBooking, ApiResult<Booking>> = (req, res) => {
  res.status(201).json({ ok: true, data: req.body });
};

export type Req<P = {}, Q = {}, B = unknown> = { params: P; query: Q; body: B };
export type Res<T> = { status(code: number): Res<T>; json(body: T): void };
export type Handler<P = {}, Q = {}, B = unknown, T = unknown> = (req: Req<P, Q, B>, res: Res<T>) => void;

export type ApiOk<T> = { ok: true; data: T };
export type ApiErr = { ok: false; error: { code: string; message: string } };
export type ApiResult<T> = ApiOk<T> | ApiErr;

import type { Req, Res } from './http.ts';
export function fakeRes<T>(sink: { body?: T; code?: number }): Res<T> { return { status(code) { sink.code = code; return this; }, json(body) { sink.body = body; } }; }
export function fakeReq<P, Q, B>(parts: { params?: P; query?: Q; body?: B }): Req<P, Q, B> { return { params: (parts.params ?? {}) as P, query: (parts.query ?? {}) as Q, body: parts.body as B }; }

import type { CreateBooking, Booking } from '../src/handler.ts';
const c: CreateBooking = { lab: 'BE-201', seats: 40, purpose: 'Lab' };
const b: Booking = { id: 'bk_1', lab: 'BE-201', seats: 40, purpose: 'Lab', status: 'PENDING' };
export { c, b };

import type { CreateBooking, Booking } from '../src/handler.ts';
import type { ApiResult } from '../src/api.ts';
export const s1: CreateBooking = { lab: 'x', seats: 40 }; // expect TS2741
export const s2: CreateBooking = { lab: 'x', seats: 'many', purpose: 'y' }; // expect TS2322
export const s3: Booking = { id: 'bk', lab: 'x', seats: 40, purpose: 'y', status: 'DONE' }; // expect TS2322
export function s4(r: ApiResult<Booking>) { return r.data; } // expect TS2339

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createBooking } from '../src/handler.ts';
import { fakeReq, fakeRes } from '../src/run.ts';
test('valid -> 201', () => { const s: { body?: any; code?: number } = {}; createBooking(fakeReq({ body: { lab: 'BE-201', seats: 40, purpose: 'Lab' } }), fakeRes(s)); assert.equal(s.code, 201); assert.equal(s.body.ok, true); assert.equal(s.body.data.lab, 'BE-201'); });
test('seats 0 -> 400', () => { const s: { body?: any; code?: number } = {}; createBooking(fakeReq({ body: { lab: 'BE-201', seats: 0, purpose: 'Lab' } }), fakeRes(s)); assert.equal(s.code, 400); assert.equal(s.body.ok, false); });

